import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import "../App.css";
DKDKDKDK

function LoginPage() {
  const [showForgotPassword, setShowForgotPassword] = useState(false);
  const [showRegister, setShowRegister] = useState(false);
  const navigate = useNavigate();
  const { login, register } = useAuth();

  // Animation variants
  const fadeUp = {
    hidden: { opacity: 0, y: 40 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.6, ease: "easeOut" } },
  };

  const modalVariants = {
    hidden: { opacity: 0, scale: 0.8 },
    visible: { opacity: 1, scale: 1, transition: { duration: 0.3 } },
    exit: { opacity: 0, scale: 0.8, transition: { duration: 0.2 } },
  };

  const handleLogin = (e) => {
    e.preventDefault();
    const username = e.target.username.value;
    const password = e.target.password.value;

    const result = login(username, password);

    if (result.success) {
      alert("로그인 성공!");
      navigate("/projects");
    } else {
      if (result.error === "userNotFound") {
        alert("존재하지 않는 아이디입니다.\n회원가입을 먼저 진행해주세요.");
      } else if (result.error === "wrongPassword") {
        alert("비밀번호가 올바르지 않습니다.");
      } else if (result.error === "pendingApproval") {
        alert("회원가입 승인 대기 중입니다.\n관리자의 승인을 기다려주세요.");
      } else if (result.error === "rejected") {
        alert("회원가입이 거부되었습니다.\n관리자에게 문의해주세요.");
      } else {
        alert("로그인 실패. 다시 시도해주세요.");
      }
    }
  };

  const handleForgotPassword = (e) => {
    e.preventDefault();
    alert("비밀번호 재설정 링크가 이메일로 전송되었습니다!");
    setShowForgotPassword(false);
  };

  const handleRegister = (e) => {
    e.preventDefault();
    const username = e.target.regUsername.value;
    const email = e.target.regEmail.value;
    const password = e.target.regPassword.value;
    const confirmPassword = e.target.regConfirmPassword.value;

    if (password !== confirmPassword) {
      alert("비밀번호가 일치하지 않습니다.");
      return;
    }

    if (password.length < 8) {
      alert("비밀번호는 8자 이상이어야 합니다.");
      return;
    }

    const result = register(username, email, password);

    if (result.success && result.pending) {
      alert("회원가입 신청이 완료되었습니다!\n관리자 승인 후 로그인이 가능합니다.");
      setShowRegister(false);
    } else if (result.error === "userExists") {
      alert("이미 존재하는 아이디입니다.\n다른 아이디를 사용해주세요.");
    } else if (result.error === "emailExists") {
      alert("이미 등록된 이메일입니다.");
    } else {
      alert("회원가입 실패. 다시 시도해주세요.");
    }
  };

  return (
    <main
      style={{
        padding: "0",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Background Pattern */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "url('data:image/svg+xml,%3Csvg width=\"60\" height=\"60\" viewBox=\"0 0 60 60\" xmlns=\"http://www.w3.org/2000/svg\"%3E%3Cg fill=\"none\" fill-rule=\"evenodd\"%3E%3Cg fill=\"%23ffffff\" fill-opacity=\"0.05\"%3E%3Cpath d=\"M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z\"/%3E%3C/g%3E%3C/g%3E%3C/svg%3E')",
          opacity: 0.3,
        }}
      />

      {/* Floating Elements */}
      <motion.div
        style={{
          position: "absolute",
          width: "400px",
          height: "400px",
          borderRadius: "50%",
          background: "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)",
          top: "-100px",
          left: "-100px",
          filter: "blur(60px)",
        }}
        animate={{
          y: [0, 30, 0],
          x: [0, 20, 0],
        }}
        transition={{
          duration: 8,
          repeat: Infinity,
          ease: "easeInOut",
        }}
      />

      <motion.div
        style={{
          position: "absolute",
          width: "300px",
          height: "300px",
          borderRadius: "50%",
          background: "linear-gradient(135deg, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0.05) 100%)",
          bottom: "-50px",
          right: "-50px",
          filter: "blur(60px)",
        }}
        animate={{
          y: [0, -30, 0],
          x: [0, -20, 0],
        }}
        transition={{
          duration: 10,
          repeat: Infinity,
          ease: "easeInOut",
        }}
      />

      {/* Login Container */}
      <motion.div
        style={{
          background: "rgba(255, 255, 255, 0.95)",
          backdropFilter: "blur(20px)",
          padding: "50px 40px",
          borderRadius: "25px",
          boxShadow: "0 20px 60px rgba(0, 0, 0, 0.3)",
          width: "100%",
          maxWidth: "450px",
          position: "relative",
          zIndex: 1,
          border: "1px solid rgba(255, 255, 255, 0.2)",
        }}
        initial="hidden"
        animate="visible"
        variants={fadeUp}
      >
        {/* Logo/Title */}
        <motion.div
          style={{
            textAlign: "center",
            marginBottom: "40px",
          }}
          variants={fadeUp}
        >
          <motion.div
            style={{
              width: "80px",
              height: "80px",
              margin: "0 auto 20px",
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              borderRadius: "20px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0 10px 30px rgba(102, 126, 234, 0.4)",
            }}
            whileHover={{ rotate: 360, scale: 1.05 }}
            transition={{ duration: 0.6 }}
          >
            <i className="fas fa-home" style={{ fontSize: "2.5em", color: "#fff" }}></i>
          </motion.div>
          <h1
            style={{
              fontSize: "2.2em",
              fontWeight: 800,
              margin: "0 0 10px",
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              backgroundClip: "text",
            }}
          >
            Assemble
          </h1>
          <p style={{ color: "#6c757d", fontSize: "1em", margin: 0 }}>
            AI 인테리어 디자인 플랫폼
          </p>
        </motion.div>

        {/* Login Form */}
        <form onSubmit={handleLogin}>
          <motion.div
            style={{ marginBottom: "25px" }}
            variants={fadeUp}
          >
            <label
              htmlFor="username"
              style={{
                display: "block",
                marginBottom: "10px",
                fontWeight: 600,
                color: "#333",
                fontSize: "0.95em",
              }}
            >
              아이디
            </label>
            <input
              type="text"
              id="username"
              placeholder="아이디를 입력하세요"
              required
              style={{
                width: "100%",
                padding: "14px 18px",
                border: "2px solid #e9ecef",
                borderRadius: "12px",
                fontSize: "1em",
                boxSizing: "border-box",
                transition: "all 0.3s ease",
                fontFamily: "inherit",
              }}
              onFocus={(e) => {
                e.target.style.borderColor = "#667eea";
                e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
              }}
              onBlur={(e) => {
                e.target.style.borderColor = "#e9ecef";
                e.target.style.boxShadow = "none";
              }}
            />
          </motion.div>

          <motion.div
            style={{ marginBottom: "30px" }}
            variants={fadeUp}
          >
            <label
              htmlFor="password"
              style={{
                display: "block",
                marginBottom: "10px",
                fontWeight: 600,
                color: "#333",
                fontSize: "0.95em",
              }}
            >
              비밀번호
            </label>
            <input
              type="password"
              id="password"
              placeholder="비밀번호를 입력하세요"
              required
              style={{
                width: "100%",
                padding: "14px 18px",
                border: "2px solid #e9ecef",
                borderRadius: "12px",
                fontSize: "1em",
                boxSizing: "border-box",
                transition: "all 0.3s ease",
                fontFamily: "inherit",
              }}
              onFocus={(e) => {
                e.target.style.borderColor = "#667eea";
                e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
              }}
              onBlur={(e) => {
                e.target.style.borderColor = "#e9ecef";
                e.target.style.boxShadow = "none";
              }}
            />
          </motion.div>

          <motion.button
            type="submit"
            style={{
              width: "100%",
              padding: "16px",
              background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
              color: "#fff",
              border: "none",
              borderRadius: "12px",
              fontSize: "1.1em",
              fontWeight: 700,
              cursor: "pointer",
              boxShadow: "0 10px 25px rgba(102, 126, 234, 0.3)",
              transition: "all 0.3s ease",
            }}
            whileHover={{
              scale: 1.02,
              boxShadow: "0 15px 35px rgba(102, 126, 234, 0.4)",
            }}
            whileTap={{ scale: 0.98 }}
            variants={fadeUp}
          >
            로그인
          </motion.button>
        </form>

        {/* Login Options */}
        <motion.div
          style={{
            marginTop: "30px",
            textAlign: "center",
            fontSize: "0.95em",
            color: "#6c757d",
          }}
          variants={fadeUp}
        >
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              setShowForgotPassword(true);
            }}
            style={{
              color: "#667eea",
              textDecoration: "none",
              fontWeight: 600,
              margin: "0 10px",
              transition: "color 0.3s ease",
            }}
            onMouseEnter={(e) => (e.target.style.color = "#764ba2")}
            onMouseLeave={(e) => (e.target.style.color = "#667eea")}
          >
            비밀번호 찾기
          </a>
          <span style={{ color: "#dee2e6" }}>|</span>
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              setShowRegister(true);
            }}
            style={{
              color: "#667eea",
              textDecoration: "none",
              fontWeight: 600,
              margin: "0 10px",
              transition: "color 0.3s ease",
            }}
            onMouseEnter={(e) => (e.target.style.color = "#764ba2")}
            onMouseLeave={(e) => (e.target.style.color = "#667eea")}
          >
            회원가입
          </a>
        </motion.div>
      </motion.div>

      {/* Forgot Password Modal */}
      <AnimatePresence>
        {showForgotPassword && (
          <motion.div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: "rgba(0, 0, 0, 0.6)",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              zIndex: 1001,
              backdropFilter: "blur(5px)",
            }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setShowForgotPassword(false)}
          >
            <motion.div
              style={{
                background: "#fff",
                padding: "40px",
                borderRadius: "25px",
                width: "90%",
                maxWidth: "500px",
                boxShadow: "0 20px 60px rgba(0, 0, 0, 0.3)",
                position: "relative",
              }}
              variants={modalVariants}
              initial="hidden"
              animate="visible"
              exit="exit"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setShowForgotPassword(false)}
                style={{
                  position: "absolute",
                  top: "20px",
                  right: "20px",
                  background: "none",
                  border: "none",
                  fontSize: "1.8em",
                  color: "#aaa",
                  cursor: "pointer",
                  transition: "color 0.3s ease",
                }}
                onMouseEnter={(e) => (e.target.style.color = "#333")}
                onMouseLeave={(e) => (e.target.style.color = "#aaa")}
              >
                &times;
              </button>

              <h2
                style={{
                  fontSize: "1.8em",
                  fontWeight: 700,
                  color: "#333",
                  marginTop: 0,
                  marginBottom: "30px",
                  textAlign: "center",
                }}
              >
                비밀번호 찾기
              </h2>

              <form onSubmit={handleForgotPassword}>
                <div style={{ marginBottom: "25px" }}>
                  <label
                    htmlFor="forgotEmail"
                    style={{
                      display: "block",
                      marginBottom: "10px",
                      fontWeight: 600,
                      color: "#555",
                    }}
                  >
                    가입 시 사용한 이메일
                  </label>
                  <input
                    type="email"
                    id="forgotEmail"
                    placeholder="이메일 주소를 입력하세요"
                    required
                    style={{
                      width: "100%",
                      padding: "14px 18px",
                      border: "2px solid #e9ecef",
                      borderRadius: "12px",
                      fontSize: "1em",
                      boxSizing: "border-box",
                      transition: "all 0.3s ease",
                    }}
                    onFocus={(e) => {
                      e.target.style.borderColor = "#667eea";
                      e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
                    }}
                    onBlur={(e) => {
                      e.target.style.borderColor = "#e9ecef";
                      e.target.style.boxShadow = "none";
                    }}
                  />
                </div>

                <motion.button
                  type="submit"
                  style={{
                    width: "100%",
                    padding: "14px",
                    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                    color: "#fff",
                    border: "none",
                    borderRadius: "12px",
                    fontSize: "1.05em",
                    fontWeight: 600,
                    cursor: "pointer",
                    transition: "all 0.3s ease",
                  }}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  비밀번호 재설정 링크 받기
                </motion.button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Register Modal */}
      <AnimatePresence>
        {showRegister && (
          <motion.div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: "rgba(0, 0, 0, 0.6)",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              zIndex: 1001,
              backdropFilter: "blur(5px)",
            }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setShowRegister(false)}
          >
            <motion.div
              style={{
                background: "#fff",
                padding: "40px",
                borderRadius: "25px",
                width: "90%",
                maxWidth: "500px",
                boxShadow: "0 20px 60px rgba(0, 0, 0, 0.3)",
                position: "relative",
                maxHeight: "90vh",
                overflowY: "auto",
              }}
              variants={modalVariants}
              initial="hidden"
              animate="visible"
              exit="exit"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                onClick={() => setShowRegister(false)}
                style={{
                  position: "absolute",
                  top: "20px",
                  right: "20px",
                  background: "none",
                  border: "none",
                  fontSize: "1.8em",
                  color: "#aaa",
                  cursor: "pointer",
                  transition: "color 0.3s ease",
                }}
                onMouseEnter={(e) => (e.target.style.color = "#333")}
                onMouseLeave={(e) => (e.target.style.color = "#aaa")}
              >
                &times;
              </button>

              <h2
                style={{
                  fontSize: "1.8em",
                  fontWeight: 700,
                  color: "#333",
                  marginTop: 0,
                  marginBottom: "30px",
                  textAlign: "center",
                }}
              >
                회원가입
              </h2>

              <form onSubmit={handleRegister}>
                <div style={{ marginBottom: "20px" }}>
                  <label
                    htmlFor="regUsername"
                    style={{
                      display: "block",
                      marginBottom: "10px",
                      fontWeight: 600,
                      color: "#555",
                    }}
                  >
                    아이디
                  </label>
                  <input
                    type="text"
                    id="regUsername"
                    name="regUsername"
                    placeholder="사용할 아이디를 입력하세요"
                    required
                    style={{
                      width: "100%",
                      padding: "14px 18px",
                      border: "2px solid #e9ecef",
                      borderRadius: "12px",
                      fontSize: "1em",
                      boxSizing: "border-box",
                      transition: "all 0.3s ease",
                    }}
                    onFocus={(e) => {
                      e.target.style.borderColor = "#667eea";
                      e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
                    }}
                    onBlur={(e) => {
                      e.target.style.borderColor = "#e9ecef";
                      e.target.style.boxShadow = "none";
                    }}
                  />
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <label
                    htmlFor="regEmail"
                    style={{
                      display: "block",
                      marginBottom: "10px",
                      fontWeight: 600,
                      color: "#555",
                    }}
                  >
                    이메일 주소
                  </label>
                  <input
                    type="email"
                    id="regEmail"
                    name="regEmail"
                    placeholder="이메일 주소를 입력하세요"
                    required
                    style={{
                      width: "100%",
                      padding: "14px 18px",
                      border: "2px solid #e9ecef",
                      borderRadius: "12px",
                      fontSize: "1em",
                      boxSizing: "border-box",
                      transition: "all 0.3s ease",
                    }}
                    onFocus={(e) => {
                      e.target.style.borderColor = "#667eea";
                      e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
                    }}
                    onBlur={(e) => {
                      e.target.style.borderColor = "#e9ecef";
                      e.target.style.boxShadow = "none";
                    }}
                  />
                </div>

                <div style={{ marginBottom: "20px" }}>
                  <label
                    htmlFor="regPassword"
                    style={{
                      display: "block",
                      marginBottom: "10px",
                      fontWeight: 600,
                      color: "#555",
                    }}
                  >
                    비밀번호
                  </label>
                  <input
                    type="password"
                    id="regPassword"
                    name="regPassword"
                    placeholder="비밀번호를 입력하세요 (8자 이상)"
                    required
                    minLength="8"
                    style={{
                      width: "100%",
                      padding: "14px 18px",
                      border: "2px solid #e9ecef",
                      borderRadius: "12px",
                      fontSize: "1em",
                      boxSizing: "border-box",
                      transition: "all 0.3s ease",
                    }}
                    onFocus={(e) => {
                      e.target.style.borderColor = "#667eea";
                      e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
                    }}
                    onBlur={(e) => {
                      e.target.style.borderColor = "#e9ecef";
                      e.target.style.boxShadow = "none";
                    }}
                  />
                </div>

                <div style={{ marginBottom: "25px" }}>
                  <label
                    htmlFor="regConfirmPassword"
                    style={{
                      display: "block",
                      marginBottom: "10px",
                      fontWeight: 600,
                      color: "#555",
                    }}
                  >
                    비밀번호 확인
                  </label>
                  <input
                    type="password"
                    id="regConfirmPassword"
                    name="regConfirmPassword"
                    placeholder="비밀번호를 다시 입력하세요"
                    required
                    style={{
                      width: "100%",
                      padding: "14px 18px",
                      border: "2px solid #e9ecef",
                      borderRadius: "12px",
                      fontSize: "1em",
                      boxSizing: "border-box",
                      transition: "all 0.3s ease",
                    }}
                    onFocus={(e) => {
                      e.target.style.borderColor = "#667eea";
                      e.target.style.boxShadow = "0 0 0 4px rgba(102, 126, 234, 0.1)";
                    }}
                    onBlur={(e) => {
                      e.target.style.borderColor = "#e9ecef";
                      e.target.style.boxShadow = "none";
                    }}
                  />
                </div>

                <motion.button
                  type="submit"
                  style={{
                    width: "100%",
                    padding: "14px",
                    background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
                    color: "#fff",
                    border: "none",
                    borderRadius: "12px",
                    fontSize: "1.05em",
                    fontWeight: 600,
                    cursor: "pointer",
                    transition: "all 0.3s ease",
                  }}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  회원가입
                </motion.button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  );
}

export default LoginPage;
